const formatMoneyInput=(e,finalize=false)=>{let el=e?.target||e;if(!el)return;let raw=String(el.value||'').replace(/[^0-9,.-]/g,'');if(raw.includes('-'))raw=(raw[0]==='-'?'-':'')+raw.slice(1).replace(/-/g,'');let parts=raw.replace('.',',').split(',');let whole=parts[0]||'';let dec=(parts[1]||'').replace(/\D/g,'').slice(0,2);if(finalize){let n=parseMoney(raw);el.value=n.toFixed(2).replace('.',',')}else{el.value=whole+(raw.includes(',')?','+dec:'')}};
