const settingsDefault={membershipTypes:['عضو مؤسس','عضو عامل','عضو منخرط','عضو شرفي','متطوع','رياضي','مدرب/مؤطر','حكم'],paymentMethods:['نقدًا','صك/شيك','تحويل CCP','تحويل بنكي','BaridiMob','الدفع الإلكتروني','أخرى'],accounts:['الصندوق','CCP','البنك','الحساب الإلكتروني','أخرى'],activityTypes:['الطيران الشراعي','الطيران الشراعي بمحرك','النماذج الجوية','المشي الجبلي','التخييم','التسلق','نشاط آخر'],statuses:['مبرمج','قيد التنفيذ','منجز','ملغى','مؤجل'],eventTypes:['تدريب','خرجة جبلية','تخييم','فعالية/تظاهرة','اجتماع/تنسيق','أخرى'],roles:['مشارك','متدرب','رياضي','مؤطر','منظم','متطوع','مسؤول','أخرى'],years:['2025','2026'],memberTableColumns:['الرقم','الاسم','تاريخ الميلاد','مكان الميلاد','الهاتف','البريد الإلكتروني','الإقامة','رقم الطوارئ','الصفة','حالة العضوية']};
