function fresh(){return{schema:'1.0',members:[],memberships:[],transactions:[],plans:[],activities:[],participants:[],attendance:[],equipment:[],incoming:[],outgoing:[],correspondence:[],meetings:[],decisions:[],tasks:[],documents:[],audit:[],years:{'2025':{status:'open',opening:0},'2026':{status:'open',opening:0}},settings:settingsDefault,packs:packsDefault}}
function load(){let n=JSON.parse(localStorage.getItem(K)||'null');if(n)return n;let o=JSON.parse(localStorage.getItem(OLD)||'null')||{},v=JSON.parse(localStorage.getItem(OV8)||'null')||{},d=fresh();d.members=o.members||[];d.memberships=o.memberships||[];d.transactions=(o.finance||[]).map(x=>({...x,id:x.id||uid('OP'),kind:x.type==='مصروف'?'دفع':'قبض',year:String(x.financialYear||String(x.date||'').slice(0,4)||'2026'),description:x.desc||x.description||'',category:x.category||''}));d.activities=o.activities||[];d.participants=o.participation||[];d.attendance=o.attendance||[];d.equipment=v.assets||[];d.plans=v.plans||[];d.correspondence=v.correspondence||[];d.meetings=v.meetings||[];d.decisions=v.decisions||[];d.tasks=v.tasks||[];d.documents=v.documents||[];d.audit=v.audit||[];d.years=v.yearMeta||d.years;d.incoming=JSON.parse(localStorage.getItem('afak_incoming_mail_v19')||'[]');d.outgoing=JSON.parse(localStorage.getItem('afak_outgoing_mail_v19')||'[]');d.settings=JSON.parse(localStorage.getItem(OS)||'null')||settingsDefault;d.packs=JSON.parse(localStorage.getItem(OP)||'null')||packsDefault;localStorage.setItem(K,JSON.stringify(d));return d}
