function go(id){document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));let f={dashboard:dashboard,members:membersPage,memberships:membershipsPage,practitioners:practitionersPage,finance:financePage,planning:planningPage,activities:activitiesPage,equipment:equipmentPage,mail:mailPage,governance:govPage,documents:docsPage,reports:reportsPage,settings:settingsPage}[id];document.getElementById('main').innerHTML=f();after(id);scrollTo(0,0)}
