function dashboard(){let y=String(new Date().getFullYear()),t=db.transactions.filter(x=>yof(x)===y&&!x.voided),i=t.filter(x=>x.kind==='قبض').reduce((s,x)=>s+Number(x.amount||0),0),e=t.filter(x=>x.kind==='دفع').reduce((s,x)=>s+Number(x.amount||0),0);return pg('لوحة القيادة','مركز المتابعة للجمعية','<div class="cards"><div class="card"><small>المنخرطون</small><strong>'+db.members.length+'</strong></div><div class="card"><small>العضويات المفعلة '+y+'</small><strong>'+db.memberships.filter(r=>String(r.year)===y&&mstate(r).active).length+'</strong></div><div class="card"><small>القبض '+y+'</small><strong>'+money(i)+'</strong></div><div class="card"><small>الرصيد '+y+'</small><strong>'+money((db.years[y]?.opening||0)+i-e)+'</strong></div></div><div class="panel"><h3>قاعدة المنصة</h3><p class="mut">العضو هو هوية دائمة، والعضوية سجل سنوي مستقل، والحركة المالية تسجل مرة واحدة، والتخطيط منفصل عن التنفيذ.</p></div><div class="panel"><h3>آخر الحركات</h3>'+recent()+'</div>')}
