function mform(m={}){let ac=Array.isArray(m.activityCodes)?m.activityCodes:[];let activityBox='<div class="field full"><label>الأنشطة المنتمي إليها</label><div class="checkgrid">'+activeActivities().map(a=>'<label class="checkitem"><input type="checkbox" class="mact" value="'+esc(a.code)+'" '+(ac.includes(a.code)?'checked':'')+'> '+esc(a.code)+' — '+esc(a.name)+'</label>').join('')+'</div><small class="mut">اختيار النشاط هنا يحدد الانتماء؛ حق الممارسة يحسب تلقائياً وفق العضوية والباقة.</small></div>';return'<div class="formgrid">'+fld('الاسم واللقب','mn',m.name)+fld('تاريخ الميلاد','md',m.dob,'date')+fld('مكان الميلاد','mb',m.birthPlace)+('<div class="field"><label>الجنس</label>'+sel('mg',['ذكر','أنثى'],m.gender)+'</div>')+fld('الهاتف','mp',m.phone,'tel')+fld('البريد الإلكتروني','me',m.email,'email')+fld('رقم الاتصال عند الطوارئ','mx',m.emergencyPhone,'tel')+fld('مقر الإقامة','ma',m.address)+fld('المهنة','mj',m.occupation)+('<div class="field"><label>الصفة في المكتب</label>'+sel('mr',['الرئيس','نائب الرئيس','الأمين العام','نائب الأمين العام','أمين المال','نائب أمين المال'],m.officeRole)+'</div>')+('<div class="field"><label>نوع المنخرط</label>'+sel('mt',db.settings.membershipTypes,m.type)+'</div>')+fld('تاريخ الانضمام','mi',m.joinDate||today(),'date')+activityBox+'<div class="field full"><label>ملاحظات</label><textarea id="mnotes">'+esc(m.notes||'')+'</textarea></div></div>'}
