function semesterForDate(date,year){let d=new Date(String(date||year+'-01-01')+'T12:00:00');if(Number.isNaN(d.getTime()))d=new Date(Number(year),0,1);return d.getMonth()<=5?{key:'S1',label:'السداسي الأول',range:'جانفي–جوان',until:String(year)+'-06-30'}:{key:'S2',label:'السداسي الثاني',range:'جويلية–ديسمبر',until:String(year)+'-12-31'}}
